using System.Collections.Generic;
using UnityEngine;

public enum ArtStyleId { Classic, Dusk, Vector, Crt }

// Switchable art styles, picked on the title screen and remembered between runs.
// Classic is the code-drawn placeholder shapes. The others swap in sprites from
// Resources/Art/<Style>/ (generated by tools/artgen) and restyle the ground. Anything a style
// has no sprite for falls back to the classic shapes.
public static class ArtStyle
{
    const string Key = "artStyle";
    public static readonly ArtStyleId[] All = { ArtStyleId.Classic, ArtStyleId.Dusk, ArtStyleId.Vector, ArtStyleId.Crt };

    // Dusk's 7-colour palette (20 Minutes Till Dawn look).
    static readonly Color DuskGround = Hex(0x1d1a2b), DuskNavy = Hex(0x2b2f4a), DuskSage = Hex(0x6f9b7a),
                          DuskDeepSage = Hex(0x3e5a4e), DuskCream = Hex(0xf0d2bc), DuskCoral = Hex(0xe5555f),
                          DuskWine = Hex(0x8c3446);   // only in the boss robes

    // Enemy radius each sprite was drawn for (matches EnemyRoster); bigger variants scale up.
    static readonly Dictionary<EnemyLook, float> drawnRadius = new Dictionary<EnemyLook, float>
    {
        { EnemyLook.Blob, 0.35f }, { EnemyLook.Bat, 0.28f }, { EnemyLook.Beast, 0.5f }, { EnemyLook.Goblin, 0.42f },
        { EnemyLook.Wizard, 0.42f }, { EnemyLook.Mushroom, 0.45f }, { EnemyLook.Pixie, 0.3f }, { EnemyLook.Mole, 0.5f },
        { EnemyLook.Treant, 1.3f }, { EnemyLook.Witch, 0.9f }, { EnemyLook.Headmaster, 0.9f }, { EnemyLook.Golem, 1.4f },
    };

    static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
    static ArtStyleId? current;

    public static ArtStyleId Current
    {
        get
        {
            if (current == null) current = (ArtStyleId)Mathf.Clamp(PlayerPrefs.GetInt(Key, 0), 0, All.Length - 1);
            return current.Value;
        }
        set
        {
            current = value;
            PlayerPrefs.SetInt(Key, (int)value);
            PlayerPrefs.Save();
        }
    }

    public static string Label(ArtStyleId s) => s == ArtStyleId.Crt ? "CRT" : s.ToString();

    // Texels per world unit, shared with the editor importer. Bullets and gems are 1 unit wide.
    public static float PixelsPerUnit(string style, string file, int width)
    {
        if (file.StartsWith("bullet") || file.StartsWith("gem")) return width;
        switch (style)
        {
            case "Dusk": return 20f;
            case "Crt": return 28f;
            default: return 128f;
        }
    }

    // The current style's sprite with this name, or null (Classic, or no such file).
    // HUD meter colours: Dusk keeps them inside its palette (coral health, sage XP).
    public static Color HealthColor => Current == ArtStyleId.Dusk ? new Color32(0xe5, 0x55, 0x5f, 255) : new Color(1f, 0.35f, 0.45f);
    public static Color XpColor => Current == ArtStyleId.Dusk ? new Color32(0x6f, 0x9b, 0x7a, 255) : new Color(0.45f, 0.75f, 1f);

    public static Sprite Get(string name)
    {
        if (Current == ArtStyleId.Classic) return null;
        string style = Current.ToString();
        string path = $"Art/{style}/{name}";
        if (cache.TryGetValue(path, out var sprite)) return sprite;

        sprite = Resources.Load<Sprite>(path);
        if (sprite == null)
        {
            // Imported as a plain texture (e.g. before the importer ran): wrap it ourselves.
            var tex = Resources.Load<Texture2D>(path);
            if (tex != null)
            {
                tex.filterMode = Current == ArtStyleId.Vector ? FilterMode.Bilinear : FilterMode.Point;
                sprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), PixelsPerUnit(style, name, tex.width));
            }
        }
        cache[path] = sprite;
        return sprite;
    }

    // Small round things (bullets, ground specks): pixel circles in the pixel styles.
    public static Sprite Round => Get("bullet") ?? SpriteFactory.Circle;
    public static Sprite Gem => Get("gem") ?? SpriteFactory.Diamond;

    public static Sprite Enemy(EnemyLook look) => Get("enemy_" + look.ToString().ToLowerInvariant());
    public static float EnemyScale(EnemyLook look, float radius) => drawnRadius.TryGetValue(look, out var r) ? radius / r : 1f;

    public static string ObstacleSprite(ObstacleStyle style) =>
        style == ObstacleStyle.Pillar ? "obstacle_pillar" : style == ObstacleStyle.Rock ? "obstacle_rock" : "obstacle_tree";

    // Dusk keeps every enemy bullet coral so threats always read the same.
    public static Color EnemyBullet(Color c) => Current == ArtStyleId.Dusk ? DuskCoral : c;

    // Death debris colours for each Dusk enemy sprite: its two main body colours (no cream, no outline),
    // so a dying slime bursts into the greens it's drawn in.
    static readonly Dictionary<EnemyLook, Color[]> duskDebris = new Dictionary<EnemyLook, Color[]>
    {
        { EnemyLook.Blob, new[] { DuskSage, DuskDeepSage } }, { EnemyLook.Bat, new[] { DuskDeepSage, DuskSage } },
        { EnemyLook.Beast, new[] { DuskDeepSage, DuskNavy } }, { EnemyLook.Goblin, new[] { DuskSage, DuskDeepSage } },
        { EnemyLook.Wizard, new[] { DuskDeepSage, DuskCoral } }, { EnemyLook.Mushroom, new[] { DuskCoral, DuskWine } },
        { EnemyLook.Pixie, new[] { DuskSage, DuskCoral } }, { EnemyLook.Mole, new[] { DuskDeepSage, DuskNavy } },
        { EnemyLook.Treant, new[] { DuskSage, DuskDeepSage } }, { EnemyLook.Witch, new[] { DuskWine, DuskSage } },
        { EnemyLook.Headmaster, new[] { DuskWine, DuskNavy } }, { EnemyLook.Golem, new[] { DuskDeepSage, DuskSage } },
    };

    public static Color[] DebrisColors(EnemyLook look) =>
        duskDebris.TryGetValue(look, out var c) ? c : new[] { DuskSage, DuskDeepSage };

    // Particle colours: Dusk snaps every spark to its palette (warm -> coral, bright and icy -> cream,
    // green and deep blue -> sage); other styles keep the colour as given.
    public static Color ParticleColor(Color c)
    {
        if (Current != ArtStyleId.Dusk) return c;
        Color.RGBToHSV(c, out float h, out float s, out float v);
        if (s < 0.3f) return v > 0.45f ? DuskCream : DuskNavy;
        if (h < 0.11f || h > 0.8f) return DuskCoral;
        if (h < 0.2f) return DuskCream;
        if (h < 0.5f) return v > 0.55f ? DuskSage : DuskDeepSage;
        return s > 0.6f ? DuskSage : DuskCream;
    }

    // Sprites can't be brightened by tint, so hit flashes go warm instead of white.
    public static Color HitFlash => Current == ArtStyleId.Classic ? Color.white : new Color(1f, 0.45f, 0.45f);

    public static void Restyle(Biome b)
    {
        switch (Current)
        {
            case ArtStyleId.Dusk:
                b.Ground = DuskGround;
                b.GroundSpeck = DuskNavy;
                b.Flowers = b.Style == ObstacleStyle.Tree ? new[] { DuskSage, DuskDeepSage, DuskCream } : new[] { DuskCream, DuskCoral };
                break;
            case ArtStyleId.Crt:
                b.Ground = new Color(0.02f, 0.02f, 0.03f);
                b.GroundSpeck = new Color(0.07f, 0.07f, 0.1f);
                break;
        }
    }

    static Color Hex(int rgb) => new Color((rgb >> 16 & 255) / 255f, (rgb >> 8 & 255) / 255f, (rgb & 255) / 255f);
}
